"""PostgreSQL bootstrap for the canonical HASSLE NFT marketplace schema."""
from __future__ import annotations
import re
from typing import Any

_TABLES = (
"""CREATE TABLE IF NOT EXISTS telegram_users (telegram_id TEXT PRIMARY KEY, username TEXT NOT NULL DEFAULT '', first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', photo_url TEXT NOT NULL DEFAULT '', language_code TEXT NOT NULL DEFAULT '', is_premium BOOLEAN NOT NULL DEFAULT FALSE, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS user_profiles (profile_id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL UNIQUE REFERENCES telegram_users(telegram_id), display_name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS telegram_sessions (token_hash TEXT PRIMARY KEY, telegram_id TEXT NOT NULL REFERENCES telegram_users(telegram_id), created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, revoked_at BIGINT)""",
"""CREATE TABLE IF NOT EXISTS telegram_initdata_uses (initdata_hash TEXT PRIMARY KEY, telegram_id TEXT NOT NULL, consumed_at BIGINT NOT NULL, expires_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS telegram_update_inbox (update_id BIGINT PRIMARY KEY, payload_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('processing','processed')), received_at BIGINT NOT NULL, lease_until BIGINT NOT NULL, processed_at BIGINT, attempts INTEGER NOT NULL DEFAULT 1)""",
"""CREATE TABLE IF NOT EXISTS user_favorites (telegram_id TEXT NOT NULL, gift_id TEXT NOT NULL, gift_json TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(telegram_id,gift_id))""",
"""CREATE TABLE IF NOT EXISTS marketplace_orders (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, owner_name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('listing','buy-order')), title TEXT NOT NULL, price TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency IN ('TON','XTR')), status TEXT NOT NULL CHECK(status IN ('active','matched','cancelled')), created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, note TEXT NOT NULL DEFAULT '', asset_type TEXT CHECK(asset_type IS NULL OR asset_type IN ('gift','username','number')), asset_id TEXT)""",
"""CREATE TABLE IF NOT EXISTS verified_assets (id TEXT PRIMARY KEY, source TEXT NOT NULL CHECK(source IN ('telegram_gift','ton_nft','telegram_username','anonymous_number')), external_asset_id TEXT NOT NULL, owner_telegram_id TEXT NOT NULL, title TEXT NOT NULL, asset_type TEXT NOT NULL CHECK(asset_type IN ('gift','username','number')), image_url TEXT NOT NULL DEFAULT '', verification_method TEXT NOT NULL CHECK(verification_method IN ('telegram_gift_owner','ton_connect_proof','telegram_username_owner','anonymous_number_owner')), verification_reference_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'verified' CHECK(status IN ('verified','revoked')), created_at BIGINT NOT NULL, verified_at BIGINT NOT NULL, revoked_at BIGINT, UNIQUE(source,external_asset_id))""",
"""CREATE TABLE IF NOT EXISTS marketplace_order_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id TEXT NOT NULL REFERENCES marketplace_orders(id), actor_user_id TEXT NOT NULL, event_type TEXT NOT NULL CHECK(event_type IN ('created','filled','cancelled','legacy_unverified')), created_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS marketplace_order_revisions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id TEXT NOT NULL REFERENCES marketplace_orders(id), actor_user_id TEXT NOT NULL, changed_fields TEXT NOT NULL DEFAULT '[]', created_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS marketplace_order_reports (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES marketplace_orders(id), reporter_user_id TEXT NOT NULL, reporter_name TEXT NOT NULL, reason TEXT NOT NULL CHECK(reason IN ('scam','misleading','inappropriate','spam','other')), details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('open','dismissed','removed')), created_at BIGINT NOT NULL, resolved_at BIGINT, resolved_by TEXT, UNIQUE(order_id,reporter_user_id))""",
"""CREATE TABLE IF NOT EXISTS api_rate_limits (user_id TEXT NOT NULL, action TEXT NOT NULL, window_started_at BIGINT NOT NULL, request_count INTEGER NOT NULL, PRIMARY KEY(user_id,action))""",
"""CREATE TABLE IF NOT EXISTS security_audit_events (id TEXT PRIMARY KEY, actor_telegram_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('telegram_session_revoked','telegram_sessions_revoked_all','ton_wallet_linked','ton_wallet_revoked','admin_report_dismissed','admin_order_removed','admin_asset_revoked')), target_type TEXT NOT NULL CHECK(target_type IN ('session','account','wallet','order_report','order','verified_asset')), target_hash TEXT NOT NULL CHECK(length(target_hash)=64), outcome TEXT NOT NULL CHECK(outcome IN ('success','denied')), metadata_json TEXT NOT NULL DEFAULT '{}', created_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS app_settings (setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL, updated_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS telegram_business_connections (telegram_id TEXT PRIMARY KEY, business_connection_id TEXT NOT NULL UNIQUE, user_chat_id TEXT NOT NULL, is_enabled BOOLEAN NOT NULL DEFAULT FALSE, can_view_gifts_and_stars BOOLEAN NOT NULL DEFAULT FALSE, can_transfer_and_upgrade_gifts BOOLEAN NOT NULL DEFAULT FALSE, can_transfer_stars BOOLEAN NOT NULL DEFAULT FALSE, updated_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS telegram_business_gift_refs (asset_id TEXT PRIMARY KEY REFERENCES verified_assets(id), owner_telegram_id TEXT NOT NULL, business_connection_id TEXT NOT NULL, owned_gift_id TEXT NOT NULL, gift_slug TEXT NOT NULL, model_sticker_file_id TEXT NOT NULL DEFAULT '', updated_at BIGINT NOT NULL, UNIQUE(business_connection_id,owned_gift_id))""",
"""CREATE TABLE IF NOT EXISTS asset_ownership_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES verified_assets(id), previous_owner_id TEXT NOT NULL, new_owner_id TEXT NOT NULL, verification_reference_hash TEXT NOT NULL, created_at BIGINT NOT NULL)""",
"""CREATE TABLE IF NOT EXISTS asset_owner_transfer_authorizations (asset_id TEXT PRIMARY KEY REFERENCES verified_assets(id), previous_owner_id TEXT NOT NULL, new_owner_id TEXT NOT NULL, verification_reference_hash TEXT NOT NULL, created_at BIGINT NOT NULL)""",
)
_INDEXES = (
"CREATE INDEX IF NOT EXISTS idx_telegram_users_updated ON telegram_users(updated_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_user_profiles_updated ON user_profiles(updated_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_telegram_sessions_user ON telegram_sessions(telegram_id,expires_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_telegram_initdata_expiry ON telegram_initdata_uses(expires_at)",
"CREATE INDEX IF NOT EXISTS idx_telegram_update_inbox_status ON telegram_update_inbox(status,lease_until)",
"CREATE INDEX IF NOT EXISTS idx_user_favorites_updated ON user_favorites(telegram_id,updated_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_orders_status_created ON marketplace_orders(status,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_orders_user_created ON marketplace_orders(user_id,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_verified_assets_owner_status ON verified_assets(owner_telegram_id,status,verified_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_order_events_order ON marketplace_order_events(order_id,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_order_revisions_order ON marketplace_order_revisions(order_id,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_order_reports_status_created ON marketplace_order_reports(status,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_business_connections_enabled ON telegram_business_connections(telegram_id,is_enabled)",
"CREATE INDEX IF NOT EXISTS idx_business_gift_refs_owner ON telegram_business_gift_refs(owner_telegram_id,updated_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_asset_ownership_history_asset ON asset_ownership_history(asset_id,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_marketplace_orders_asset ON marketplace_orders(asset_id,status)",
"CREATE INDEX IF NOT EXISTS idx_security_audit_actor_created ON security_audit_events(actor_telegram_id,created_at DESC)",
"CREATE INDEX IF NOT EXISTS idx_security_audit_action_created ON security_audit_events(action,created_at DESC)",
)
_FUNCTION = "CREATE OR REPLACE FUNCTION hassle_nft_verified_asset_metadata_immutable() RETURNS trigger LANGUAGE plpgsql AS $hassle_nft$\nBEGIN\n -- A verified transfer must have a one-use server authorization.\n IF NOT (\n     NEW.status = 'verified'\n     AND NEW.owner_telegram_id IS DISTINCT FROM OLD.owner_telegram_id\n     AND NEW.source IS NOT DISTINCT FROM OLD.source\n     AND NEW.external_asset_id IS NOT DISTINCT FROM OLD.external_asset_id\n     AND EXISTS (\n         SELECT 1 FROM asset_owner_transfer_authorizations auth\n         WHERE auth.asset_id = OLD.id\n           AND auth.previous_owner_id = OLD.owner_telegram_id\n           AND auth.new_owner_id = NEW.owner_telegram_id\n           AND auth.verification_reference_hash = NEW.verification_reference_hash\n     )\n )\n THEN\n     RAISE EXCEPTION USING MESSAGE = 'verified asset metadata is immutable';\n END IF;\n DELETE FROM asset_owner_transfer_authorizations\n  WHERE asset_id = NEW.id\n    AND previous_owner_id = OLD.owner_telegram_id\n    AND new_owner_id = NEW.owner_telegram_id;\n RETURN NEW;\nEND; $hassle_nft$"
_AUDIT_FUNCTION = "CREATE OR REPLACE FUNCTION hassle_nft_security_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $hassle_nft$\nBEGIN\n RAISE EXCEPTION USING MESSAGE = 'security audit events are immutable';\nEND; $hassle_nft$"
_APPEND_ONLY_FUNCTION = "CREATE OR REPLACE FUNCTION hassle_nft_append_only_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $append_only$\nBEGIN\n RAISE EXCEPTION USING MESSAGE = 'append-only history is immutable';\nEND; $append_only$"


def _expected_table_columns() -> dict[str, set[str]]:
    """Extract declared column names from the reviewed CREATE TABLE statements."""
    expected: dict[str, set[str]] = {}
    prefix = "CREATE TABLE IF NOT EXISTS "
    table_constraints = {"CONSTRAINT", "PRIMARY", "UNIQUE", "FOREIGN", "CHECK", "EXCLUDE"}

    for statement in _TABLES:
        if not statement.startswith(prefix):
            raise RuntimeError("Unrecognized PostgreSQL marketplace table DDL")
        opening = statement.find("(", len(prefix))
        closing = statement.rfind(")")
        if opening < 0 or closing <= opening:
            raise RuntimeError("Malformed PostgreSQL marketplace table DDL")
        table_name = statement[len(prefix):opening].strip()
        body = statement[opening + 1:closing]
        definitions: list[str] = []
        start = 0
        depth = 0
        in_string = False
        index = 0
        while index < len(body):
            char = body[index]
            if char == "'":
                if in_string and index + 1 < len(body) and body[index + 1] == "'":
                    index += 2
                    continue
                in_string = not in_string
            elif not in_string and char == "(":
                depth += 1
            elif not in_string and char == ")":
                depth -= 1
            elif not in_string and depth == 0 and char == ",":
                definitions.append(body[start:index])
                start = index + 1
            index += 1
        definitions.append(body[start:])

        columns: set[str] = set()
        for definition in definitions:
            match = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*)", definition)
            if not match:
                raise RuntimeError(f"Could not parse a column in PostgreSQL table {table_name}")
            name = match.group(1)
            if name.upper() not in table_constraints:
                columns.add(name)
        expected[table_name] = columns
    return expected


def verify_postgres_marketplace_schema(connection: Any) -> dict[str, Any]:
    tables = {str(r["table_name"]) for r in connection.execute("SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_type='BASE TABLE'").fetchall()}
    expected_tables = {name for name in ("telegram_users","user_profiles","telegram_sessions","telegram_initdata_uses","telegram_update_inbox","user_favorites","marketplace_orders","verified_assets","marketplace_order_events","marketplace_order_revisions","marketplace_order_reports","api_rate_limits","app_settings","telegram_business_connections","telegram_business_gift_refs","asset_ownership_history","asset_owner_transfer_authorizations","security_audit_events")}
    column_rows = connection.execute(
        "SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=current_schema()"
    ).fetchall()
    actual_columns: dict[str, set[str]] = {}
    for row in column_rows:
        actual_columns.setdefault(str(row["table_name"]), set()).add(str(row["column_name"]))
    expected_columns = _expected_table_columns()
    indexes = {str(r["indexname"]) for r in connection.execute("SELECT indexname FROM pg_indexes WHERE schemaname=current_schema()").fetchall()}
    expected_indexes = {q.split("IF NOT EXISTS ",1)[1].split(" ",1)[0] for q in _INDEXES}
    triggers = connection.execute("SELECT t.tgname,c.relname,p.proname,t.tgenabled FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND n.nspname=current_schema()").fetchall()
    trigger = next((r for r in triggers if r["tgname"]=="verified_assets_metadata_immutable"),None)
    audit_update = next((r for r in triggers if r["tgname"]=="security_audit_events_no_update"),None)
    audit_delete = next((r for r in triggers if r["tgname"]=="security_audit_events_no_delete"),None)
    audit_truncate = next((r for r in triggers if r["tgname"]=="security_audit_events_no_truncate"),None)
    problems=[]
    if expected_tables-tables: problems.append("missing tables: "+", ".join(sorted(expected_tables-tables)))
    for table_name, expected in expected_columns.items():
        actual = actual_columns.get(table_name, set())
        missing = expected - actual
        unexpected = actual - expected
        if missing:
            problems.append(f"missing columns in {table_name}: "+", ".join(sorted(missing)))
        if unexpected:
            problems.append(f"unexpected columns in {table_name}: "+", ".join(sorted(unexpected)))
    if expected_indexes-indexes: problems.append("missing indexes: "+", ".join(sorted(expected_indexes-indexes)))
    if trigger is None or (trigger["relname"],trigger["proname"],trigger["tgenabled"])!=("verified_assets","hassle_nft_verified_asset_metadata_immutable","O"):
        problems.append("missing or disabled verified-assets immutability trigger")
    if audit_update is None or (audit_update["relname"],audit_update["proname"],audit_update["tgenabled"])!=("security_audit_events","hassle_nft_security_audit_immutable","O"):
        problems.append("missing or disabled security audit update guard")
    if audit_delete is None or (audit_delete["relname"],audit_delete["proname"],audit_delete["tgenabled"])!=("security_audit_events","hassle_nft_security_audit_immutable","O"):
        problems.append("missing or disabled security audit delete guard")
    if audit_truncate is None or (audit_truncate["relname"],audit_truncate["proname"],audit_truncate["tgenabled"])!=("security_audit_events","hassle_nft_security_audit_immutable","O"):
        problems.append("missing or disabled security audit truncate guard")
    append_only_tables = ("marketplace_order_events", "marketplace_order_revisions", "asset_ownership_history")
    for table in append_only_tables:
        for action in ("update", "delete", "truncate"):
            name = f"{table}_no_{action}"
            trigger = next((r for r in triggers if r["tgname"] == name), None)
            if trigger is None or (trigger["relname"], trigger["proname"], trigger["tgenabled"]) != (
                table, "hassle_nft_append_only_history_immutable", "O"
            ):
                problems.append(f"missing or disabled append-only history guard {name}")
    if problems: raise RuntimeError("PostgreSQL marketplace schema verification failed: "+"; ".join(problems))
    return {"verified":True,"tables_verified":len(expected_tables),"columns_verified":sum(len(columns) for columns in expected_columns.values()),"indexes_verified":len(expected_indexes),"triggers_verified":13}

def initialize_postgres_marketplace_schema(connection: Any) -> dict[str, Any]:
    if not callable(getattr(connection,"execute",None)) or not bool(getattr(connection,"supports_for_update",False)):
        raise TypeError("A PostgreSQL adapter connection is required")
    for statement in _TABLES: connection.execute(statement)
    # Migrate the audit allow-list in place for databases created by earlier builds.
    connection.execute("ALTER TABLE security_audit_events DROP CONSTRAINT IF EXISTS security_audit_events_action_check")
    connection.execute("ALTER TABLE security_audit_events ADD CONSTRAINT security_audit_events_action_check CHECK(action IN ('telegram_session_revoked','telegram_sessions_revoked_all','ton_wallet_linked','ton_wallet_revoked','admin_report_dismissed','admin_order_removed','admin_asset_revoked'))")
    connection.execute("ALTER TABLE security_audit_events DROP CONSTRAINT IF EXISTS security_audit_events_target_type_check")
    connection.execute("ALTER TABLE security_audit_events ADD CONSTRAINT security_audit_events_target_type_check CHECK(target_type IN ('session','account','wallet','order_report','order','verified_asset'))")
    for statement in _INDEXES: connection.execute(statement)
    connection.execute(_FUNCTION)
    connection.execute(_AUDIT_FUNCTION)
    connection.execute(_APPEND_ONLY_FUNCTION)
    connection.execute("DROP TRIGGER IF EXISTS verified_assets_metadata_immutable ON verified_assets")
    connection.execute("CREATE TRIGGER verified_assets_metadata_immutable BEFORE UPDATE OF source,external_asset_id,owner_telegram_id,title,asset_type,image_url,verification_method,verification_reference_hash,verified_at ON verified_assets FOR EACH ROW EXECUTE FUNCTION hassle_nft_verified_asset_metadata_immutable()")
    connection.execute("DROP TRIGGER IF EXISTS security_audit_events_no_update ON security_audit_events")
    connection.execute("DROP TRIGGER IF EXISTS security_audit_events_no_delete ON security_audit_events")
    connection.execute("DROP TRIGGER IF EXISTS security_audit_events_no_truncate ON security_audit_events")
    connection.execute("CREATE TRIGGER security_audit_events_no_update BEFORE UPDATE ON security_audit_events FOR EACH ROW EXECUTE FUNCTION hassle_nft_security_audit_immutable()")
    connection.execute("CREATE TRIGGER security_audit_events_no_delete BEFORE DELETE ON security_audit_events FOR EACH ROW EXECUTE FUNCTION hassle_nft_security_audit_immutable()")
    connection.execute("CREATE TRIGGER security_audit_events_no_truncate BEFORE TRUNCATE ON security_audit_events FOR EACH STATEMENT EXECUTE FUNCTION hassle_nft_security_audit_immutable()")
    for table in ("marketplace_order_events", "marketplace_order_revisions", "asset_ownership_history"):
        for action in ("update", "delete", "truncate"):
            name = f"{table}_no_{action}"
            connection.execute(f"DROP TRIGGER IF EXISTS {name} ON {table}")
            if action == "truncate":
                connection.execute(
                    f"CREATE TRIGGER {name} BEFORE TRUNCATE ON {table} "
                    "FOR EACH STATEMENT EXECUTE FUNCTION hassle_nft_append_only_history_immutable()"
                )
            else:
                connection.execute(
                    f"CREATE TRIGGER {name} BEFORE {action.upper()} ON {table} "
                    "FOR EACH ROW EXECUTE FUNCTION hassle_nft_append_only_history_immutable()"
                )
    return {**verify_postgres_marketplace_schema(connection),"tables_created_or_verified":len(_TABLES)}
